  e_exists: ["That user already exists.", "Ese usuario ya existe.", "Dieser Benutzer existiert bereits.", "Cet utilisateur existe déjà.", "Quell'utente esiste già.", "そのユーザーは既に存在します。", "该用户已存在。", "Esse utilizador já existe."],
