  // ---- the pages of the summary, the Wi-Fi, the firmware from GitHub, the help and the about
  e_bad_json: ["The request is not valid JSON.", "La petición no es un JSON válido.", "Die Anfrage ist kein gültiges JSON.", "La requête n'est pas un JSON valide.", "La richiesta non è un JSON valido.", "リクエストが有効な JSON ではありません。", "请求不是有效的 JSON。", "O pedido não é um JSON válido."],
  e_bad_url: ["The address of the update is not the official one.", "La dirección de la actualización no es la oficial.", "Die Adresse des Updates ist nicht die offizielle.", "L'adresse de la mise à jour n'est pas l'officielle.", "L'indirizzo dell'aggiornamento non è quello ufficiale.", "アップデートのアドレスが公式のものではありません。", "更新地址不是官方地址。", "O endereço da atualização não é o oficial."],
  e_checksum_mismatch: ["The downloaded firmware does not match the checksum of the release: it was refused and nothing changed.", "El firmware descargado no coincide con la suma de comprobación de la versión: se rechazó y no se cambió nada.", "Die heruntergeladene Firmware stimmt nicht mit der Prüfsumme der Version überein: Sie wurde abgelehnt, nichts wurde geändert.", "Le firmware téléchargé ne correspond pas à la somme de contrôle de la version : il a été refusé et rien n'a changé.", "Il firmware scaricato non corrisponde alla somma di controllo della versione: è stato rifiutato e nulla è cambiato.", "ダウンロードしたファームウェアがリリースのチェックサムと一致しません。拒否され、何も変更されていません。", "下载的固件与该版本的校验和不符：已拒绝，未做任何更改。", "O firmware descarregado não coincide com a soma de controlo da versão: foi recusado e nada mudou."],
  e_client_init: ["The download could not be started.", "No se pudo iniciar la descarga.", "Der Download konnte nicht gestartet werden.", "Le téléchargement n'a pas pu démarrer.", "Non è stato possibile avviare il download.", "ダウンロードを開始できませんでした。", "无法开始下载。", "Não foi possível iniciar a transferência."],
  e_connect_failed: ["The download did not connect: check the node's network and try again.", "La descarga no conectó: revisa la red del nodo e inténtalo de nuevo.", "Der Download hat keine Verbindung bekommen: Prüfen Sie das Netz des Knotens und versuchen Sie es erneut.", "Le téléchargement ne s'est pas connecté : vérifiez le réseau du nœud et réessayez.", "Il download non si è connesso: controlla la rete del nodo e riprova.", "ダウンロードに接続できませんでした。ノードのネットワークを確認して、もう一度お試しください。", "下载未能连接：请检查节点的网络后重试。", "A transferência não se ligou: verifique a rede do nó e tente de novo."],
  e_no_asset: ["The release has no firmware for this board.", "La versión no trae firmware para esta placa.", "Die Version enthält keine Firmware für diese Platine.", "La version ne contient pas de firmware pour cette carte.", "La versione non contiene firmware per questa scheda.", "このリリースにはこのボード用のファームウェアがありません。", "该版本没有适用于此电路板的固件。", "A versão não traz firmware para esta placa."],
  e_no_asset_for_board: ["A newer release exists, but it has no firmware image for this board.", "Hay una versión más nueva, pero no trae imagen de firmware para esta placa.", "Es gibt eine neuere Version, aber sie enthält kein Firmware-Image für diese Platine.", "Une version plus récente existe, mais elle ne contient pas d'image de firmware pour cette carte.", "Esiste una versione più recente, ma non contiene un'immagine firmware per questa scheda.", "新しいリリースがありますが、このボード用のファームウェアイメージが含まれていません。", "存在更新的版本，但其中没有适用于此电路板的固件映像。", "Existe uma versão mais recente, mas não traz imagem de firmware para esta placa."],
  e_no_checksum: ["The release carries no checksum file next to the firmware image, so it is not installed.", "La versión no trae el archivo de suma de comprobación junto a la imagen del firmware, así que no se instala.", "Die Version enthält neben dem Firmware-Image keine Prüfsummendatei und wird deshalb nicht installiert.", "La version ne contient pas de fichier de somme de contrôle à côté de l'image du firmware, elle n'est donc pas installée.", "La versione non contiene il file della somma di controllo accanto all'immagine del firmware, quindi non viene installata.", "リリースにファームウェアイメージと並ぶチェックサムファイルがないため、インストールされません。", "该版本在固件镜像旁没有校验和文件，因此不会安装。", "A versão não traz ficheiro de soma de controlo junto à imagem de firmware, por isso não se instala."],
  e_no_memory: ["The node ran out of memory.", "Al nodo se le acabó la memoria.", "Dem Knoten ist der Speicher ausgegangen.", "Le nœud n'a plus de mémoire.", "Al nodo è finita la memoria.", "ノードのメモリが不足しました。", "节点内存不足。", "O nó ficou sem memória."],
  e_no_release: ["No release was found.", "No se encontró ninguna versión publicada.", "Es wurde keine veröffentlichte Version gefunden.", "Aucune version publiée n'a été trouvée.", "Non è stata trovata alcuna versione pubblicata.", "公開されたリリースが見つかりませんでした。", "未找到已发布的版本。", "Não foi encontrada nenhuma versão publicada."],
  e_no_slot: ["There is no other slot to copy to.", "No hay otra ranura a la que copiar.", "Es gibt keinen anderen Slot zum Kopieren.", "Il n'y a pas d'autre emplacement où copier.", "Non c'è un altro slot dove copiare.", "コピー先のスロットがありません。", "没有可复制到的另一个槽。", "Não há outra ranhura para onde copiar."],
  e_no_task: ["The update could not be started (no free task).", "No se pudo iniciar la actualización (no hay tarea libre).", "Das Update konnte nicht gestartet werden (keine freie Aufgabe).", "La mise à jour n'a pas pu démarrer (aucune tâche libre).", "Non è stato possibile avviare l'aggiornamento (nessun task libero).", "アップデートを開始できませんでした（空きタスクがありません）。", "无法开始更新（没有空闲任务）。", "Não foi possível iniciar a atualização (sem tarefa livre)."],
  e_not_newer: ["That firmware is not newer than the one running.", "Ese firmware no es más nuevo que el que está en marcha.", "Diese Firmware ist nicht neuer als die laufende.", "Ce firmware n'est pas plus récent que celui en cours.", "Quel firmware non è più recente di quello in uso.", "そのファームウェアは動作中のものより新しくありません。", "该固件并不比正在运行的更新。", "Esse firmware não é mais novo do que o que está em execução."],
  e_ota_busy: ["An installation from GitHub is already running.", "Ya hay una instalación desde GitHub en curso.", "Eine Installation von GitHub läuft bereits.", "Une installation depuis GitHub est déjà en cours.", "È già in corso un'installazione da GitHub.", "GitHub からのインストールが既に実行中です。", "已有一个来自 GitHub 的安装正在进行。", "Já está a decorrer uma instalação a partir do GitHub."],
